    public CompletableFuture<Object> fetchDepositsOrWithdrawalsHelper(String type, String code, Object since, Object limit, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> currency = null;
            Map<String, Object> request = new HashMap<String, Object>() {{}};
            if (!java.util.Objects.equals(code, null))
            {
                currency = this.currency((String) (code));
                request.put("coin", currency.get("id"));
            }
            if (!java.util.Objects.equals(since, null))
            {
                request.put("startTime", since);
            }
            io.github.ccxt.base.Pair<Map<String, Object>, Map<String, Object>> requestUntilparamsUntilVariable = this.handleUntilOption("endTime", (Map<String, Object>) (request), (Map<String, Object>) (parameters), 1);
            Map<String, Object> requestUntil = requestUntilparamsUntilVariable.first();
            Map<String, Object> paramsUntil = requestUntilparamsUntilVariable.second();
            if (!java.util.Objects.equals(limit, null))
            {
                ((Map<String, Object>)requestUntil).put("limit", limit);
            }
            List<Object> response = new ArrayList<Object>(Arrays.asList());
            if (java.util.Objects.equals(type, "deposits"))
            {
                response = (this.privateGetApiV1AccountDepositOrders(this.extend(requestUntil, paramsUntil))).join();
            } else if (java.util.Objects.equals(type, "withdrawals"))
            {
                response = (this.privateGetApiV1AccountWithdrawOrders(this.extend(requestUntil, paramsUntil))).join();
            }
            return this.parseTransactions(response, currency, Helpers.toLongOrNull(since), Helpers.toLongOrNull(limit), paramsUntil);
        });

    }

    public Object parseTransaction(Map<String, Object> transaction, Map<String, Object> currency)
    {
        //
        // fetchDeposits & fetchWithdrawals
        //
        //     {
        //         "time": 1499865549590,
        //         "id": 100234,
        //         "coinName": "EOS",
        //         "statusCode": "DEPOSIT_CAN_WITHDRAW",
        //         "status": "2", // 2=SUCCESS, 11=REJECT, 12=AUDIT
        //         "address": "deposit2bb",
        //         "txId": "98A3EA560C6B3336D348B6C83F0F95ECE4F1F5919E94BD006E5BF3BF264FACFC",
        //         "txIdUrl": "",
        //         "requiredConfirmTimes": "5",
        //         "confirmTimes": "5",
        //         "quantity": "1.01",
        //         "coin": "EOS",                     // present in "fetchDeposits"
        //         "coinId ":"BHC",                   // present in "fetchWithdrawals"
        //         "addressTag": "19012584",          // present in "fetchDeposits"
        //         "addressExt":"address tag",        // present in "fetchWithdrawals"
        //         "fromAddress": "clarkkent",        // present in "fetchDeposits"
        //         "fromAddressTag": "19029901"       // present in "fetchDeposits"
        //         "arriveQuantity":"14",             // present in "fetchWithdrawals"
        //         "walletHandleTime":"1536232111669",// present in "fetchWithdrawals"
        //         "feeCoinId ":"BHC",                // present in "fetchWithdrawals"
        //         "feeCoinName ":"BHC",              // present in "fetchWithdrawals"
        //         "fee":"0.1",                       // present in "fetchWithdrawals"
        //         "kernelId":"",                     // present in "fetchWithdrawals"
        //         "isInternalTransfer": false        // present in "fetchWithdrawals"
        //     }
        //
        // withdraw
        //
        //     {
        //         "status": 0,
        //         "success": true,
        //         "needBrokerAudit": false, // Do you need a brokerage review?
        //         "id": "423885103582776064",
        //         "refuseReason":"" // failure rejection reason
        //     }
        //
        Long timestamp = this.safeInteger(transaction, "time");
        String currencyId = this.safeString2(transaction, "coin", "coinId");
        String code = this.safeCurrencyCode(currencyId, currency);
        String feeString = this.safeString(transaction, "fee");
        String feeCoin = this.safeString(transaction, "feeCoinName");
        Map<String, Object> fee = null;
        if (!java.util.Objects.equals(feeString, null))
        {
            fee = Helpers.newMap(
                "cost", this.parseNumber(feeString),
                "currency", this.safeCurrencyCode(feeCoin, (Map<String, Object>) null)
            );
        }
        String tagTo = this.safeString2(transaction, "addressTag", "addressExt");
        String tagFrom = this.safeString(transaction, "fromAddressTag");
        String addressTo = this.safeString(transaction, "address");
        String addressFrom = this.safeString(transaction, "fromAddress");
        Boolean isWithdraw = (transaction.containsKey("arriveQuantity"));
        String type = ((Boolean.TRUE.equals(isWithdraw))) ? "withdrawal" : "deposit";
        return Helpers.newMap(
            "info", transaction,
            "id", this.safeString(transaction, "id"),
            "txid", this.safeString(transaction, "txId"),
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "network", null,
            "address", null,
            "addressTo", addressTo,
            "addressFrom", addressFrom,
            "tag", null,
            "tagTo", tagTo,
            "tagFrom", tagFrom,
            "type", type,
            "amount", this.safeNumber(transaction, "quantity", (Object) null),
            "currency", code,
            "status", this.parseTransactionStatus(this.safeString(transaction, "status")),
            "updated", null,
            "fee", fee,
            "comment", null,
            "internal", null
        );
    }

    public String parseTransactionStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "2", "pending" );
            put( "12", "pending" );
            put( "11", "failed" );
            put( "3", "ok" );
        }};
        if (java.util.Objects.equals(status, null))
        {
            return null;
        }
        return this.safeString(statuses, status, status);
    }

